import {
  checkIfTypeSupportsScoring,
  getItemTypeMutationString,
  getItemTypeString,
  getMutationPayload,
  ITEM_TYPES,
  ITEM_TYPE_MUTATION_NAME,
} from '..';

describe('ITEM_TYPES', () => {
  it('should have ITEM_TYPES', () => {
    expect(ITEM_TYPES).toEqual({
      ASSETS: 'ASSETS',
      BARCODE: 'BARCODE',
      CHECKMARK: 'CHECKMARK',
      DATE_TIME: 'DATE_TIME',
      DATE: 'DATE',
      EMPLOYEE: 'EMPLOYEE',
      FORMULA: 'FORMULA',
      FREE_RESPONSE: 'FREE_RESPONSE',
      MEASUREMENT: 'MEASUREMENT',
      MULTIPLE_CHOICE: 'MULTIPLE_CHOICE',
      PHOTO: 'PHOTO',
      QR_CODE: 'QR_CODE',
      RATING_1_10: 'RATING_1_10',
      RATING_1_5: 'RATING_1_5',
      RATING_CUSTOM: 'RATING_CUSTOM',
      SHORT_ENTRY: 'SHORT_ENTRY',
      SIGNATURE: 'SIGNATURE',
      STOPWATCH: 'STOPWATCH',
      SUB_LIST: 'SUB_LIST',
      SUBTITLE: 'SUBTITLE',
      TEXT: 'TEXT',
      TIME: 'TIME',
      YES_NO: 'YES_NO',
    });
  });

  it('checkIfTypeSupportsScoring works', () => {
    expect(checkIfTypeSupportsScoring(ITEM_TYPES.MULTIPLE_CHOICE)).toBe(true);
    expect(checkIfTypeSupportsScoring(ITEM_TYPES.RATING_1_5)).toBe(true);
    expect(checkIfTypeSupportsScoring(ITEM_TYPES.RATING_1_10)).toBe(true);
    expect(checkIfTypeSupportsScoring(ITEM_TYPES.YES_NO)).toBe(true);
    expect(checkIfTypeSupportsScoring(ITEM_TYPES.CHECKMARK)).toBe(false);
  });

  it('should have ITEM_TYPE_MUTATION_NAME', () => {
    expect(ITEM_TYPE_MUTATION_NAME).toEqual({
      ASSETS: 'Assets',
      BARCODE: 'Barcode',
      CHECKMARK: 'Checkmark',
      DATE_TIME: 'DateTime',
      DATE: 'Date',
      EMPLOYEE: 'Employee',
      FORMULA: 'Formula',
      FREE_RESPONSE: 'FreeResponse',
      MEASUREMENT: 'Measurement',
      MULTIPLE_CHOICE: 'MultipleChoice',
      PHOTO: 'Photo',
      QR_CODE: 'QRCode',
      RATING_1_10: 'RatingTen',
      RATING_1_5: 'RatingFive',
      RATING_CUSTOM: 'RatingCustom',
      SHORT_ENTRY: 'ShortEntry',
      SIGNATURE: 'Signature',
      STOPWATCH: 'Stopwatch',
      SUB_LIST: 'Sublist',
      SUBTITLE: 'Subtitle',
      TEXT: 'Text',
      TIME: 'Time',
      YES_NO: 'YesNo',
    });
  });

  it('should get item type mutation name', () => {
    expect(getItemTypeString(ITEM_TYPES.CHECKMARK)).toBe('Checkmark');
  });

  it('should throw error if invalid type for getItemTypeString', () => {
    const consoleSpy = jest
      .spyOn(console, 'error')
      .mockImplementation(() => {});
    getItemTypeString('invalid_type');
    expect(consoleSpy).toHaveBeenCalledWith('getItemTypeString: Invalid type');
  });

  it('should be a valid graphql string', () => {
    const payload = 'payload';
    const query = getItemTypeMutationString(
      'MyMutationName',
      ITEM_TYPES.RATING_1_10,
      payload,
    );
    expect(query).toBe(`
    mutation MyMutationName_SaveItemTemplate_Mutation($input: SaveItemTemplateRatingTenInput!) {
      saveItemTemplateRatingTen(input: $input) {
        payload
      }
    }`);
  });

  it('should throw error if invalid type for getItemTypeMutationString', () => {
    const consoleSpy = jest
      .spyOn(console, 'error')
      .mockImplementation(() => {});
    getItemTypeMutationString('component', 'invalid_type', 'payload');
    expect(consoleSpy).toHaveBeenCalledWith(
      'getItemTypeMutationString: Invalid type',
    );
  });

  it('should return mutation payload', () => {
    const mutationPayload = {
      saveItemTemplateStopwatch: {
        itemTemplate: {
          id: '123',
        },
      },
    };
    expect(getMutationPayload(ITEM_TYPES.STOPWATCH, mutationPayload)).toEqual({
      itemTemplate: {
        id: '123',
      },
    });
  });

  it('should throw error if invalid type for getMutationPayload', () => {
    const consoleSpy = jest
      .spyOn(console, 'error')
      .mockImplementation(() => {});
    getMutationPayload('invalid_type', {});
    expect(consoleSpy).toHaveBeenCalledWith('getMutationPayload: Invalid type');
  });
});
